python3 - <<'EOF'
import json
segs={json.loads(l)['segment_id']: json.loads(l)['text'] for l in open('corpus/segments.jsonl') if l.strip()}
def norm(s): return " ".join(s.split())
checks = {
 'R13-003': ['"permissions": [','"background"','extension_pages','script-src','unsafe-eval','MV2'],
 'R13-009': ['service_worker','background.html','script src="./commons.js"','<script src="./commons.js"></script><script src="./background.js"></script>'],
 'R13-018': ['three files','Change `background.page` to `background.service_worker`','options.js`','the only files that matter'],
 'R13-024': ['"service_worker": "background.js"','Successfully replaced'],
 'R13-028': ["importScripts('commons.js');",'Successfully replaced'],
 'R13-036': ["if I wrap `window` calls in `typeof window !== 'undefined'`",'that should satisfy the validator','should satisfy the validator if it\'s looking for direct usage of `window` in a worker.'],
 'R13-057': ['Successfully replaced 1 block(s) in /work/run/out/background.js.'],
}
for sid,qs in checks.items():
    n=norm(segs[sid])
    for q in qs:
        print(sid, norm(q) in n, repr(q))
EOF

